CREATE SEQUENCE sales_plan_numbers;
CREATE SEQUENCE allocation_numbers;
CREATE TABLE sales_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE DEFAULT('SP-'||lpad(nextval('sales_plan_numbers')::text,8,'0')),project_id uuid NOT NULL REFERENCES projects(id),customer_id uuid NOT NULL,target_weight numeric(14,6) NOT NULL CHECK(target_weight>0),status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')),remark text NOT NULL DEFAULT '',created_by uuid REFERENCES users(id),origin text NOT NULL DEFAULT 'BUSINESS' CHECK(origin IN ('BUSINESS','LEGACY')),created_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,FOREIGN KEY(project_id,customer_id) REFERENCES customers(project_id,id),CHECK(origin='LEGACY' OR created_by IS NOT NULL));
CREATE TABLE allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE DEFAULT('PREP-'||lpad(nextval('allocation_numbers')::text,8,'0')),plan_id uuid NOT NULL REFERENCES sales_plans(id),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','LOCKED','RELEASED')),created_by uuid REFERENCES users(id),origin text NOT NULL DEFAULT 'BUSINESS' CHECK(origin IN ('BUSINESS','LEGACY')),remark text NOT NULL DEFAULT '',locked_at timestamptz,released_at timestamptz,release_reason text,created_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,CHECK(origin='LEGACY' OR created_by IS NOT NULL));
CREATE TABLE allocation_items(allocation_id uuid REFERENCES allocations(id),bundle_id uuid REFERENCES bundles(id),PRIMARY KEY(allocation_id,bundle_id));
CREATE TABLE reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),allocation_id uuid NOT NULL REFERENCES allocations(id),bundle_id uuid NOT NULL REFERENCES bundles(id),weight numeric(14,6) NOT NULL CHECK(weight>0),locked_by uuid REFERENCES users(id),locked_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,released_by uuid REFERENCES users(id),release_reason text,origin text NOT NULL DEFAULT 'BUSINESS' CHECK(origin IN ('BUSINESS','LEGACY')),CHECK(origin='LEGACY' OR locked_by IS NOT NULL),CHECK((released_at IS NULL AND released_by IS NULL AND release_reason IS NULL) OR(released_at IS NOT NULL AND released_by IS NOT NULL AND length(trim(release_reason))>0)));
CREATE UNIQUE INDEX one_active_reservation ON reservations(bundle_id) WHERE released_at IS NULL;
CREATE INDEX reservations_order ON reservations(allocation_id);
CREATE FUNCTION reservation_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE b bundles;p sales_plans;a allocations; BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Reservation history cannot be deleted' USING ERRCODE='23514'; END IF;
 SELECT * INTO a FROM allocations WHERE id=NEW.allocation_id FOR UPDATE;
 SELECT * INTO p FROM sales_plans WHERE id=a.plan_id FOR UPDATE;
 SELECT * INTO b FROM bundles WHERE id=NEW.bundle_id FOR UPDATE;
 IF TG_OP='INSERT' THEN
  IF NEW.origin='LEGACY' AND current_user='musonoi_owner' THEN RETURN NEW; END IF;
  IF NEW.origin<>'BUSINESS' OR a.status<>'DRAFT' OR p.status<>'OPEN' OR b.physical_status<>'IN_STOCK' OR p.project_id<>b.project_id OR NEW.weight<>b.net_weight THEN RAISE EXCEPTION 'Invalid whole-bundle reservation' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM allocation_items WHERE allocation_id=a.id AND bundle_id=b.id) THEN RAISE EXCEPTION 'Bundle not in preparation order' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM users u JOIN role_permissions rp ON rp.role_code=u.role_code WHERE u.id=NEW.locked_by AND u.active AND rp.permission_code='allocation:write') THEN RAISE EXCEPTION 'Reservation actor unauthorized' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM user_scopes s JOIN locations l ON l.id=b.location_id WHERE s.user_id=NEW.locked_by AND s.project_id=p.project_id AND(s.customer_id IS NULL OR s.customer_id=p.customer_id) AND(s.warehouse_id IS NULL OR s.warehouse_id=l.warehouse_id)) THEN RAISE EXCEPTION 'Reservation scope denied' USING ERRCODE='23514'; END IF;
  IF coalesce((SELECT sum(r.weight) FROM reservations r JOIN allocations x ON x.id=r.allocation_id WHERE x.plan_id=p.id AND r.released_at IS NULL),0)+NEW.weight>p.target_weight THEN RAISE EXCEPTION 'Sales plan target exceeded' USING ERRCODE='23514'; END IF;
 ELSE
  IF OLD.released_at IS NOT NULL OR NEW.allocation_id<>OLD.allocation_id OR NEW.bundle_id<>OLD.bundle_id OR NEW.weight<>OLD.weight OR NEW.locked_at<>OLD.locked_at OR NEW.locked_by IS DISTINCT FROM OLD.locked_by OR NEW.origin<>OLD.origin OR NEW.released_at IS NULL THEN RAISE EXCEPTION 'Reservation history immutable except one authorized release' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM users u JOIN role_permissions rp ON rp.role_code=u.role_code WHERE u.id=NEW.released_by AND u.active AND rp.permission_code='allocation:release') THEN RAISE EXCEPTION 'Release actor unauthorized' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM user_scopes s JOIN locations l ON l.id=b.location_id WHERE s.user_id=NEW.released_by AND s.project_id=p.project_id AND(s.customer_id IS NULL OR s.customer_id=p.customer_id) AND(s.warehouse_id IS NULL OR s.warehouse_id=l.warehouse_id)) THEN RAISE EXCEPTION 'Release scope denied' USING ERRCODE='23514'; END IF;
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER reservation_rules BEFORE INSERT OR UPDATE OR DELETE ON reservations FOR EACH ROW EXECUTE FUNCTION reservation_guard();
-- Preserve V2.1 opening reservations without inventing historical operators/times.
INSERT INTO sales_plans(code,project_id,customer_id,target_weight,origin,remark) SELECT 'LEGACY-'||reserved_for_customer_id::text,project_id,reserved_for_customer_id,sum(net_weight),'LEGACY','V2.1 opening reservation snapshot; original operator/time unknown' FROM bundles WHERE reserved_for_customer_id IS NOT NULL AND physical_status='IN_STOCK' GROUP BY project_id,reserved_for_customer_id;
INSERT INTO allocations(code,plan_id,status,origin,remark) SELECT 'LEGACY-'||id::text,id,'LOCKED','LEGACY','Opening snapshot imported at migration time, not historical lock time' FROM sales_plans WHERE origin='LEGACY';
INSERT INTO allocation_items SELECT a.id,b.id FROM allocations a JOIN sales_plans p ON p.id=a.plan_id JOIN bundles b ON b.project_id=p.project_id AND b.reserved_for_customer_id=p.customer_id WHERE a.origin='LEGACY' AND b.physical_status='IN_STOCK';
INSERT INTO reservations(allocation_id,bundle_id,weight,origin) SELECT i.allocation_id,b.id,b.net_weight,'LEGACY' FROM allocation_items i JOIN allocations a ON a.id=i.allocation_id JOIN bundles b ON b.id=i.bundle_id WHERE a.origin='LEGACY';
INSERT INTO audit_logs(action,entity_type,after_data) SELECT 'legacy_reservations_imported','reservations',jsonb_build_object('count',count(*),'source','V2.1 snapshot; operator/time unknown') FROM reservations WHERE origin='LEGACY';
CREATE OR REPLACE VIEW inventory_view AS SELECT b.id AS uuid,b.bundle_no AS id,b.project_id,b.customer_id,l.warehouse_id,c.name AS customer,l.code AS location,t.code AS batch,b.net_weight AS weight,CASE WHEN b.physical_status='OUTBOUND' THEN '已出库' WHEN r.id IS NOT NULL THEN '已预留' ELSE '在库' END AS status,CASE b.sample_status WHEN 'NOT_SAMPLED' THEN '未取样' WHEN 'SAMPLING' THEN '取样中' ELSE '已取样' END AS sample,to_char(b.inbound_date,'YYYY-MM-DD') AS date,b.grade,b.purity,b.data_kind,b.version,p.customer_id AS allocated_customer_id,ac.name AS allocated_customer,a.code AS allocation_code,p.code AS sales_plan_code FROM bundles b JOIN customers c ON c.id=b.customer_id JOIN locations l ON l.id=b.location_id JOIN batches t ON t.id=b.batch_id LEFT JOIN reservations r ON r.bundle_id=b.id AND r.released_at IS NULL LEFT JOIN allocations a ON a.id=r.allocation_id LEFT JOIN sales_plans p ON p.id=a.plan_id LEFT JOIN customers ac ON ac.id=p.customer_id;
GRANT SELECT,INSERT,UPDATE ON sales_plans,allocations,reservations TO musonoi_app;
GRANT SELECT,INSERT ON allocation_items,inventory_events TO musonoi_app;
